async function openPr() {
    if (process.env.NEXT_PUBLIC_STATIC_PREVIEW === "1") { setError("PR publishing is unavailable in review previews. Export JSON to keep your lab."); return; }
    if (inFlight.current) return;
    const issues = validateLabDraft(draft);
    if (issues.length) { setError(issues[0]); return; }
    inFlight.current = true;
    setBusy(true); setError("");
    try {
      const response = await fetch("/api/author/pr", { method: "POST", headers: { "Content-Type": "application/json" }, body: source });
      const data = await response.json();
      if (!response.ok) throw new Error(data.error || "The draft PR couldn’t be opened.");
      if (typeof data.url !== "string" || !data.url.startsWith("https://github.com/PostHog/twig.com/pull/")) throw new Error("GitHub did not return a PR link. Retry to check its status.");
      setResult({ source, url: data.url });
      trackTwigEvent("twig_lab_author_pr_requested", { outcome: "opened" });
    } catch (error) {
      setError(error instanceof Error ? error.message : "The draft PR couldn’t be opened. Your browser draft is safe.");
      trackTwigEvent("twig_lab_author_pr_requested", { outcome: "failed" });
    } finally { inFlight.current = false; setBusy(false); }
  }

