    try {
      const contents = format === "json" ? JSON.stringify(draft, null, 2) : authorHandoff(draft);
      const url = URL.createObjectURL(new Blob([contents], { type: format === "json" ? "application/json" : "text/markdown" }));
      const anchor = document.createElement("a");
      anchor.href = url;
      anchor.download = format === "json" ? "posthog-lab.json" : "posthog-lab-agent-brief.md";
      anchor.click();
      window.setTimeout(() => URL.revokeObjectURL(url), 1000);
      trackTwigEvent("twig_lab_author_exported", { format, step_count: draft.steps.length });
    } catch {
      setError("The export couldn’t be created. Try again.");
      trackTwigEvent("twig_lab_author_error", { operation: "export" });
    }
  }

async function importDraft(event: ChangeEvent<HTMLInputElement>) {
    const file = event.target.files?.[0];
    event.target.value = "";
    if (!file) return;
    try {
      if (file.size > 2_000_000) throw new Error("Choose a JSON file smaller than 2 MB.");
      const next = parseLabDraft(JSON.parse(await file.text()));
      change(next);
      setError("");
      trackTwigEvent("twig_lab_author_imported", { step_count: next.steps.length });
    } catch {
      setError("That file isn’t a valid guided activity export. Choose a version 1 JSON export smaller than 2 MB. Your current draft is unchanged.");
      trackTwigEvent("twig_lab_author_error", { operation: "import" });
    }
