  labId: TouchpointId,
  pageKind: TwigPageKind
) {
  const run = resetTwigLabRun(labId, pageKind);
  if (!run) return;
  if (run.startedNewRun) {
    trackTwigEvent("twig_lab_started", {
      lab_id: labId,
      lab_run_id: run.id,
      page_kind: run.pageKind,
      entry_point: "reset",
