export function captureTwigException(error: unknown, context: { surface: string; stayId?: string }) {
  const exceptionType = error instanceof TypeError ? "TypeError" : error instanceof RangeError ? "RangeError" : error instanceof Error ? "Error" : "Unknown";
  publishInspectionActivity(
    "$exception",
    {
      exception_type: exceptionType,
      surface: context.surface
    }
  );
  if (!initTwigErrorTracking()) return;
  posthog.captureException(error, {
    surface: context.surface,
    ...(context.stayId ? { stay_id: context.stayId } : {}),
  });
}

