export function trackTwigEvent<Event extends TwigEventName>(
  event: Event,
  properties: TwigEventMap[Event],
  inspectionContext?: InspectionContext
) {
  publishInspectionActivity(event, properties, inspectionContext);
  publishAuthorPreviewAction(event, properties);
  if (!isTwigAnalyticsHost()) return;
  initTwigAnalytics();
  const eventProperties = {
    analytics_schema_version: ANALYTICS_SCHEMA_VERSION,
    ...properties,
  };
  posthog.capture(event, eventProperties);
  if (isLearnHandoffActive()) {
    websiteLearnAnalytics?.capture(event, {
      ...eventProperties,
      learn_source: "posthog.com",
      learn_volume: "product-analytics",
    });
  }
}

